        raise ServiceError(400, "reason must be a string")
    if len(reason) < 1 or len(reason) > MAX_REASON_LENGTH:
        raise ServiceError(
            400,
            f"reason must be 1 to {MAX_REASON_LENGTH} characters long",
        )
    if not reason.strip():
        raise ServiceError(400, "reason must be non-blank")
    return reason

